import sys

def parse(raw):
    try:
        return int(raw)
    except ValueError:
        sys.exit(2)

for raw in ('1', 'bad', '2'):
    value = parse(raw)
    print('invalid' if value is None else f'ok:{value}')

def parse(raw):
    try:
        return int(raw)
    except ValueError:
        return None

for raw in ('1', 'bad', '2'):
    value = parse(raw)
    print('invalid' if value is None else f'ok:{value}')

state = {'integrity_ok': False}
if not state['integrity_ok']:
    print('unsafe state')
    raise SystemExit(3)
print('serving requests')

import threading

lock = threading.Lock()

def notify():
    if not lock.acquire(timeout=0.05):
        return 'blocked'
    try:
        return 'notified'
    finally:
        lock.release()

def update():
    with lock:
        return notify()

print(update())

